func (ks *keys) skipField(line []byte, p int) int {
	if ks.hasTab {
		for p < len(line) && line[p] != ks.tab {
			p++
		}
		return p
	}
	for p < len(line) && isBlank(line[p]) {
		p++
	}
	for p < len(line) && !isBlank(line[p]) {
		p++
	}
	return p
}
