func TestPasswdSortsByUID(t *testing.T) {
	chartertest.Verifies(t, claims.SW_261126_JHC8, "passwd-numeric")
	in := "root:x:0:0\nbob:x:1000:1000\nd:x:2:2\nn:x:65534:65534\nc:x:100:5\n"
	want := "root:x:0:0\nd:x:2:2\nc:x:100:5\nbob:x:1000:1000\nn:x:65534:65534\n"
	if got := sorted(t, in, "-t:", "-k3,3n"); got != want {
		t.Errorf("sort -t: -k3,3n = %q, want %q", got, want)
	}
}

func TestKeysCompareInTurn(t *testing.T) {
	chartertest.Verifies(t, claims.SW_261126_JHC8, "multiple-keys")
	in := "2 b\n10 a\n9 b\n1 a\n"
	want := "10 a\n1 a\n9 b\n2 b\n"
	if got := sorted(t, in, "-k2,2", "-k1,1nr"); got != want {
		t.Errorf("sort -k2,2 -k1,1nr = %q, want %q", got, want)
	}
}

func TestAKeyWithoutAnEndRunsToTheLineEnd(t *testing.T) {
	chartertest.Verifies(t, claims.SW_261126_JHC8, "key-to-line-end")
	in := "z:a:2\ny:a:1\n"
	if got := sorted(t, in, "-t:", "-k2"); got != "y:a:1\nz:a:2\n" {
		t.Errorf("sort -t: -k2 = %q, want the third field to decide", got)
	}
	// With the key one field wide the keys tie and the whole line decides.
	if got := sorted(t, "y:a:2\nz:a:1\n", "-t:", "-k2,2"); got != "y:a:2\nz:a:1\n" {
		t.Errorf("sort -t: -k2,2 = %q, want the whole-line tie-break", got)
	}
}

func TestBlanksBelongToAFieldWithoutT(t *testing.T) {
	chartertest.Verifies(t, claims.SW_261126_JHC8, "blanks-in-field")
	in := "x  b\ny a\n"
	// Field two of the first line is "  b", which sorts before " a".
	if got := sorted(t, in, "-k2,2"); got != "x  b\ny a\n" {
		t.Errorf("sort -k2,2 = %q, want the leading blanks compared", got)
	}
	if got := sorted(t, in, "-k2b,2"); got != "y a\nx  b\n" {
		t.Errorf("sort -k2b,2 = %q, want the blanks skipped", got)
	}
}

func TestKeysStartAndEndAtCharacters(t *testing.T) {
	chartertest.Verifies(t, claims.SW_261126_JHC8, "char-positions")
	in := "azzb\nbzza\nayya\n"
	if got := sorted(t, in, "-k1.2,1.3"); got != "ayya\nazzb\nbzza\n" {
		t.Errorf("sort -k1.2,1.3 = %q, want yy before zz, ties by line", got)
	}
}

func TestOnlyAKeyWithoutOptionsTakesTheGlobalOnes(t *testing.T) {
	chartertest.Verifies(t, claims.SW_261126_JHC8, "inherit-global")
	in := "a 10\nb 9\nc 9\n"
	if got := sorted(t, in, "-k2,2", "-n", "-r"); got != "a 10\nc 9\nb 9\n" {
		t.Errorf("sort -k2,2 -n -r = %q, want 10 first, then the nines reversed", got)
	}
	// The key keeps its own n and is not reversed; -r reverses the tie.
	if got := sorted(t, in, "-k2,2n", "-r"); got != "c 9\nb 9\na 10\n" {
		t.Errorf("sort -k2,2n -r = %q, want the nines first, reversed", got)
	}
}

func TestBadKeysAndTabsAreRefused(t *testing.T) {
	chartertest.Verifies(t, claims.SW_261126_JHC8, "bad-specs-refused")
	for _, args := range [][]string{
		{"-k0"}, {"-k1.0"}, {"-k1x"}, {"-t::"}, {"-t", ""}, {"-k1d"}, {"-t:", "-t,"},
	} {
		var out, errOut bytes.Buffer
		code := run(args, strings.NewReader("b\na\n"), &out, &errOut)
		if code != 2 || out.Len() != 0 || errOut.Len() == 0 {
			t.Errorf("sort %q: exit %d, stdout %q, stderr %q; want exit 2, a message and no output", args, code, out.String(), errOut.String())
		}
	}
}
